  selecionados: selecionados.length, paginasComErro: falhas.length, errosAmostra: falhas.slice(0, 8),
};
if (!selecionados.length) return [{ json: { vazio: true, estatisticas } }];
return selecionados.map(s => ({ json: { ...s, estatisticas } }));

